feed:
	{{ config.title }}
		{%- if term %} - {{ term.name }}
		{%- endif -%}

	{%- if config.description %}
	{{ config.description }}
	{%- endif %}


	Zola
	{% if last_updated is defined %}{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}
	{{ feed_url | safe }}
	{%- for page in pages %}

		{{ page.title }}
        {%- if page.extra.author %}

            {{ page.extra.author }}

        {%- endif %}
		{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
		{% if page.updated %}{{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% else %}{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}


		{{ page.permalink | safe }}
        {%- if page.summary %}
        {{ page.summary }}
        {%- endif %}
		{{ page.content }}

	{%- endfor %}
